CREATE TABLE rol (id SERIAL PRIMARY KEY, nombre TEXT NOT NULL UNIQUE);
CREATE TABLE usuario (id SERIAL PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE, creado_en TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE usuario_rol (usuario_id INTEGER NOT NULL REFERENCES usuario(id), rol_id INTEGER NOT NULL REFERENCES rol(id), PRIMARY KEY(usuario_id, rol_id));
CREATE TABLE paciente (id SERIAL PRIMARY KEY, usuario_id INTEGER NOT NULL UNIQUE REFERENCES usuario(id), nombre TEXT NOT NULL);
CREATE TABLE profesional (id SERIAL PRIMARY KEY, usuario_id INTEGER NOT NULL UNIQUE REFERENCES usuario(id), nombre TEXT NOT NULL);
CREATE TABLE disponibilidad (id SERIAL PRIMARY KEY, profesional_id INTEGER NOT NULL REFERENCES profesional(id), franja_inicio TIMESTAMPTZ NOT NULL, franja_fin TIMESTAMPTZ NOT NULL, CHECK (franja_fin > franja_inicio), UNIQUE(profesional_id, franja_inicio));
CREATE TABLE cita (id SERIAL PRIMARY KEY, paciente_id INTEGER NOT NULL REFERENCES paciente(id), profesional_id INTEGER NOT NULL REFERENCES profesional(id), franja_inicio TIMESTAMPTZ NOT NULL, franja_fin TIMESTAMPTZ NOT NULL, estado TEXT NOT NULL DEFAULT 'scheduled' CHECK (estado IN ('scheduled','attended','cancelled','no_show')), creado_en TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX cita_active_slot_uq ON cita(profesional_id, franja_inicio) WHERE estado <> 'cancelled';
CREATE INDEX cita_patient_idx ON cita(paciente_id, franja_inicio);
CREATE INDEX cita_prof_idx ON cita(profesional_id, franja_inicio);
CREATE INDEX cita_state_idx ON cita(estado);
CREATE TABLE encuentro (id SERIAL PRIMARY KEY, cita_id INTEGER NOT NULL REFERENCES cita(id), version INTEGER NOT NULL CHECK (version > 0), replaced_id INTEGER REFERENCES encuentro(id), notes TEXT NOT NULL, diagnosis TEXT NOT NULL, author_id INTEGER NOT NULL REFERENCES profesional(id), creado_en TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(cita_id, version));
CREATE TABLE adjunto (id SERIAL PRIMARY KEY, encuentro_id INTEGER NOT NULL REFERENCES encuentro(id), filename TEXT NOT NULL, mime_type TEXT NOT NULL, storage_path TEXT NOT NULL, creado_en TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE auditoria (id SERIAL PRIMARY KEY, usuario_id INTEGER REFERENCES usuario(id), accion TEXT NOT NULL, recurso_tipo TEXT NOT NULL, recurso_id TEXT NOT NULL, creado_en TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX disponibilidad_prof_idx ON disponibilidad(profesional_id, franja_inicio);
CREATE INDEX auditoria_filter_idx ON auditoria(usuario_id, accion, creado_en);
CREATE FUNCTION prevent_append_only_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only relation'; END $$;
CREATE TRIGGER encuentro_append_only BEFORE UPDATE OR DELETE ON encuentro FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation();
CREATE TRIGGER auditoria_append_only BEFORE UPDATE OR DELETE ON auditoria FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation();
